UPDATE maintenance_requests
SET status='NEEDS_LOCALIZATION', failure_reason=$2, updated_at=now()
WHERE id=$1::uuid;
INSERT INTO batch_items(batch_id,request_id,visual_evidence,localization,confidence)
VALUES ($3::uuid,$1::uuid,$4::jsonb,$5::jsonb,$6)
ON CONFLICT (batch_id,request_id) DO UPDATE SET visual_evidence=EXCLUDED.visual_evidence,localization=EXCLUDED.localization,confidence=EXCLUDED.confidence;
SELECT $1::uuid AS request_id, 'NEEDS_LOCALIZATION' AS outcome;

