const s = $('Normalize Localization').first().json;
const body = $json.body ?? {};
const manual = Boolean(s.manual_ifc_global_id);
const found = manual ? ($json.statusCode === 200) : Boolean(body.found);
const asset = manual ? {global_id:body.global_id,ifc_class:body.ifc_class,name:body.name,storey:body.storey,space:body.space} : body;
return [{json:{...s,ifc_found:found,asset}}];

