const p = $json;
return [{json:{...p, agent_input: JSON.stringify({
  task:'Classify and rank this end-of-day maintenance batch.',
  rules:{
    severity:'integer 1-5 based on observed damage and safety signals',
    operational_impact:'integer 1-5 for effect on safe/normal room use',
    required_skill:'one of carpentry, plumbing, electrical, hvac, general',
    complexity_factor:'number 0.80-1.50',
    priority_formula:'severity*10 + (safety_risk?20:0) + operational_impact*3 + min(community_reports,5)*2 + min(age_days,5) - (1-confidence)*10; clamp 0..100',
    cost:'use matching cost_rules base_min/base_max and multiply by complexity_factor; if no exact skill use general',
    authority:'advisory only; do not approve, dispatch or close tickets'
  },
  items:p.items,
  non_dispatchable_items:p.exceptions,
  cost_rules:p.cost_rules
})}}];

const base = $('Load Batch Payload').first().json;
const raw = $json.output ?? $json;
const report = typeof raw === 'string' ? JSON.parse(raw) : raw;
const sourceItems = Array.isArray(base.items) ? base.items : JSON.parse(base.items || '[]');
const rules = Array.isArray(base.cost_rules) ? base.cost_rules : JSON.parse(base.cost_rules || '[]');
const byId = new Map(sourceItems.map(i => [String(i.request_id), i]));
const ruleMap = new Map(rules.map(r => [`${r.required_skill}:${r.severity}`, r]));
const now = Date.now();
const validated = [];
for (const a of (report.items || [])) {
  const src = byId.get(String(a.request_id));
  if (!src) continue;
  const severity = Math.max(1, Math.min(5, Math.round(Number(a.severity || 1))));
  const impact = Math.max(1, Math.min(5, Math.round(Number(a.operational_impact || 1))));
  const safety = Boolean(a.safety_risk);
  const skill = ['carpentry','plumbing','electrical','hvac','general'].includes(String(a.required_skill)) ? String(a.required_skill) : 'general';
  const complexity = Math.max(0.8, Math.min(1.5, Number(a.complexity_factor || 1)));
  const confidence = Number(src.visual_evidence?.visual_confidence ?? src.confidence ?? 0.5);
  const reports = Number(src.community_reports || 0);
  const ageDays = Math.max(0, (now - new Date(src.created_at).getTime()) / 86400000);
  const score = Math.max(0, Math.min(100, severity*10 + (safety?20:0) + impact*3 + Math.min(reports,5)*2 + Math.min(ageDays,5) - (1-confidence)*10));
  const rule = ruleMap.get(`${skill}:${severity}`) || ruleMap.get(`general:${severity}`) || {base_min:0,base_max:0};
  const costMin = Math.round(Number(rule.base_min)*complexity*100)/100;
  const costMax = Math.round(Number(rule.base_max)*complexity*100)/100;
  validated.push({
    request_id:String(a.request_id), severity, operational_impact:impact, safety_risk:safety,
    required_skill:skill, complexity_factor:complexity, estimated_cost_min:costMin,
    estimated_cost_max:costMax, priority_score:Math.round(score*100)/100,
    ranking_rationale:String(a.ranking_rationale || 'Ranked from validated severity, safety, operational impact, evidence confidence and cost.'),
    damage_description:String(src.visual_evidence?.damage_description || 'Maintenance damage'),
    ifc_global_id:src.ifc_global_id, ifc_class:src.ifc_class, ifc_name:src.ifc_name,
    ifc_storey:src.ifc_storey, ifc_space:src.ifc_space,
    visual_evidence:src.visual_evidence, localization:src.localization
  });
}
// Safe fallback: missing agent items are classified conservatively and remain visible.
for (const src of sourceItems) if (!validated.some(v => v.request_id === String(src.request_id))) {
  const confidence = Number(src.visual_evidence?.visual_confidence ?? src.confidence ?? 0.3);
  validated.push({request_id:String(src.request_id),severity:3,operational_impact:3,safety_risk:false,required_skill:'general',complexity_factor:1,
    estimated_cost_min:160,estimated_cost_max:350,priority_score:Math.max(0,39-(1-confidence)*10),
    ranking_rationale:'Conservative fallback because the Agent output did not contain this request.',
    damage_description:String(src.visual_evidence?.damage_description || 'Maintenance damage'),ifc_global_id:src.ifc_global_id,ifc_class:src.ifc_class,ifc_name:src.ifc_name,ifc_storey:src.ifc_storey,ifc_space:src.ifc_space,visual_evidence:src.visual_evidence,localization:src.localization});
}
validated.sort((a,b)=>b.priority_score-a.priority_score || b.severity-a.severity || b.estimated_cost_max-a.estimated_cost_max);
validated.forEach((v,i)=>{v.final_rank=i+1;v.priority_label=v.priority_score>=75?'CRITICAL':v.priority_score>=55?'HIGH':v.priority_score>=35?'MEDIUM':'LOW';});
const totalMin = validated.reduce((s,v)=>s+v.estimated_cost_min,0);
const totalMax = validated.reduce((s,v)=>s+v.estimated_cost_max,0);
const exceptions = Array.isArray(base.exceptions) ? base.exceptions : JSON.parse(base.exceptions || '[]');
const rows = validated.map(v=>`<tr><td>${v.final_rank}</td><td>${v.ifc_name||v.ifc_global_id}</td><td>${v.damage_description}</td><td>${v.severity}/5</td><td>${v.priority_label} (${v.priority_score})</td><td>€${v.estimated_cost_min.toFixed(2)}–€${v.estimated_cost_max.toFixed(2)}</td><td>${v.ranking_rationale}</td></tr>`).join('');
const exceptionRows = exceptions.map(e=>`<tr><td>${e.source_file_name||e.request_id}</td><td>${e.status}</td><td>${e.ifc_name||e.ifc_global_id||'Not grounded'}</td><td>${e.failure_reason||'Attached to active ticket'}</td></tr>`).join('');
const exceptionHtml = exceptionRows ? `<h3>Non-dispatchable requests</h3><table border="1" cellpadding="6" cellspacing="0"><tr><th>Evidence</th><th>Status</th><th>Asset</th><th>Reason/action</th></tr>${exceptionRows}</table>` : '';
const duplicateNote = Number(base.same_batch_duplicate_count||0)>0 ? `<p><b>Same-asset reports consolidated inside this batch:</b> ${base.same_batch_duplicate_count}. They will become supporting evidence on the primary ticket.</p>` : '';
const html = `<h2>CBM end-of-day maintenance report</h2><p>${report.batch_summary||'Batch triage completed.'}</p><p><b>Estimated portfolio cost:</b> €${totalMin.toFixed(2)}–€${totalMax.toFixed(2)}</p>${duplicateNote}<table border="1" cellpadding="6" cellspacing="0"><tr><th>Rank</th><th>Asset</th><th>Damage</th><th>Severity</th><th>Priority</th><th>Cost range</th><th>Decision rationale</th></tr>${rows}</table>${exceptionHtml}<p><b>Control:</b> No dispatch occurs until the FM approves this report.</p>`;
return [{json:{batch_id:base.batch_id,validated_items:validated,agent_report:{...report,validated_total_cost_min:totalMin,validated_total_cost_max:totalMax,non_dispatchable_items:exceptions},report_html:html}}];
